SELECT version() AS version;
SELECT count(*) AS session_count FROM sys_stat_activity;
SELECT state, count(*) AS cnt FROM sys_stat_activity GROUP BY state ORDER BY cnt DESC;

-- 1. 先确认表上次分析时间（只读）：
SELECT schemaname, relname, last_analyze, last_autoanalyze, n_live_tup
FROM sys_stat_user_tables
WHERE schemaname = '<SCHEMA>' AND relname = '<TABLE>';
-- 2. 确认后在非高峰执行（谨慎）：
-- DANGER: ANALYZE <SCHEMA>.<TABLE>;

-- 1. 先确认（只读查询）：
SELECT pid, usename, datname, state, query_start, query FROM sys_stat_activity WHERE pid = <PID>;
-- 2. 确认无误后再执行（危险）：
-- DANGER: SELECT pg_terminate_backend(<PID>);

SELECT spcname, sys_size_pretty(sys_tablespace_size(spcname)) AS size
FROM sys_tablespace
ORDER BY sys_tablespace_size(spcname) DESC;

-- 1. 先确认归档与备份（只读）：
SHOW archive_mode;
SELECT * FROM sys_stat_archiver;
-- 2. 恢复为危险操作，先停库、先在测试库全流程演练：
-- DANGER: sys_rman restore -D <数据目录> -R <备份仓库目录>
-- DANGER: 恢复后按手册用 WAL 归档做时间点恢复（PITR），切勿在生产库直接演练。

SELECT application_name, client_addr, state, sync_state,
  sent_lsn, write_lsn, flush_lsn, replay_lsn
FROM sys_stat_replication;
-- 备库延迟（在备库执行）：
-- SELECT now() - pg_last_xact_replay_timestamp() AS replay_delay;

SELECT rolname, rolsuper, rolcanlogin, rolconnlimit
FROM pg_roles
ORDER BY rolname;
